import{_ as s,o as e,c as t,a2 as p}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"晚晴初","description":"","frontmatter":{"title":"晚晴初","date":"2026-11-20T00:00:00.000Z","seq":210,"categories":["美文","全宋词"],"collection":"《全宋词 · 柳永》","tags":["全宋词","宋"],"poem":true,"poem_quote":false,"author":"柳永","source_book":"全宋词"},"headers":[],"relativePath":"blogs/全宋词·柳永/晚晴初.md","filePath":"blogs/全宋词·柳永/晚晴初.md"}'),o={name:"blogs/全宋词·柳永/晚晴初.md"};function l(c,a,n,r,m,_){return e(),t("div",null,[...a[0]||(a[0]=[p('<h1 id="晚晴初" tabindex="-1">晚晴初 <a class="header-anchor" href="#晚晴初" aria-label="Permalink to &quot;晚晴初&quot;">​</a></h1><p class="poem-meta">宋 · 柳永　·　十二时・忆少年</p><div class="poem"><p class="poem-stanza">晚晴初，淡烟笼月，风透蟾光如洗。</p><p class="poem-stanza">觉翠帐、凉生秋思。</p><p class="poem-stanza">渐入微寒天气。</p><p class="poem-stanza">败叶敲窗，西风满院，睡不成还起。</p><p class="poem-stanza">更漏咽、滴破忧心，万感并生，都在离人愁耳。</p><p class="poem-stanza">天怎知、当时一句，做得十分萦系。</p><p class="poem-stanza">夜永有时，分明枕上，觑着孜孜地。</p><p class="poem-stanza">烛暗时酒醒，元来又是梦里。</p><p class="poem-stanza">睡觉来、披衣独坐，万种无憀情意。</p><p class="poem-stanza">怎得伊来，重谐云雨，再整馀香被。</p><p class="poem-stanza">祝告天发愿，从今永无抛弃。</p></div>',3)])])}const u=s(o,[["render",l]]);export{d as __pageData,u as default};
